10 11 Zero InitializationA 3-D array can be initialized with zero by using {0} during declaration. This initializes all elements of a numeric array to 0.Using {0} automatically sets every element of the 3-D array to zero.This method is applicable to numeric arrays or types that can be converted to numeric values.Syntaxint arr[2][3][2] = { 0 }Example: Program to Initialize 3D Array with Zero
            C

    #include <stdio.h>

int main() {

    // Initializing a 2x3x2 3D array
    int arr[2][3][2] = {0};

    // Printing the 3D array
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 3; j++) {
            for (int k = 0; k < 2; k++) {
                printf("%d ", arr[i][j][k]);
            }
            printf("\n");
        }
        printf("\n");
    }

    return 0;
}

