0 0 Runtime Initialization Using LoopsRuntime initialization assigns values to a 3-D array during program execution instead of at compile time. It is useful when values are entered by the user or generated dynamically.It is performed using three nested loops, where the loops traverse the depth, rows, and columns of the array.Runtime initialization is commonly used for user input, generated values, or copying data from other arrays.Syntaxint arr[2][2][2];for (int i = 0; i < 2; i++)    for (int j = 0; j < 2; j++)        for (int k = 0; k < 2; k++)            scanf("%d", &arr[i][j][k]);Example: Program to Initialize 3D Array Using Loops
            C

    #include <stdio.h>

int main() {

    // Defining a 2x3x2 3D array
    int arr[2][3][2];

    // Variable to assign values to array elements
    int count = 1;

    // Initializing the array using loops
    for (int i = 0; i < 2; i++)
        for (int j = 0; j < 3; j++)
            for (int k = 0; k < 2; k++)
                arr[i][j][k] = count++;

    // Printing the 3D array
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 3; j++) {
            for (int k = 0; k < 2; k++) {
                printf("%d ", arr[i][j][k]);
            }
            printf("\n");
        }
        printf("\n");
    }

    return 0;
}

